begin;

-- Curriculum apply SQL generated by lib/curriculum/apply-sql.ts.
-- REVIEW BEFORE RUNNING in the Supabase SQL Editor. ROBIN never applies this automatically.
-- Adds only: existing rows are never updated or deleted (ON CONFLICT DO NOTHING).
-- Planned: 0 semesters, 0 courses, 1 modules, 1 lessons.

-- New modules
insert into public.modules (course_id, slug, title, description, position)
select c.id, v.slug, v.title, v.description, v.position
from public.courses c
cross join (values ('logic-foundations', 'Logic Foundations', 'Propositions and the basic connectives of propositional logic.', 1)) as v(slug, title, description, position)
where c.slug = 'discrete-math' on conflict (course_id, slug) do nothing;

-- New lessons
insert into public.lessons (module_id, slug, title, summary, estimated_minutes, position)
select mo.id, v.slug, v.title, v.summary, v.estimated_minutes, v.position
from public.courses c
join public.modules mo on mo.course_id = c.id
cross join (values ('propositions', 'Propositions and Connectives', 'Distinguish propositions and evaluate negation, conjunction, and disjunction.', 16, 1)) as v(slug, title, summary, estimated_minutes, position)
where c.slug = 'discrete-math' and mo.slug = 'logic-foundations' on conflict (module_id, slug) do nothing;

commit;
